package script

import (
	"encoding/hex"
	"testing"

	"github.com/abesuite/abec/chainhash"
	"github.com/abesuite/abec/wire"
)

func TestParseAutScript(t *testing.T) {
	memo, _ := hex.DecodeString("")
	gotScript, err := ParseAutScript(wire.TxVersion, chainhash.InvalidHash, memo)
	if err != nil {
		t.Errorf("ParseAutScript() error = %v", err)
		return
	}
	t.Logf("script type %d", gotScript.Type())
}
